def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    indices = np.arange(len(bins), dtype=float)
    fit_score = 1.0 / (np.power(remaining, 2.0) + 1e-4)
    index_penalty = 1.0 + indices ** 2.0
    scores = np.where(valid, fit_score / index_penalty, -np.inf)
    return scores

